// Returns factorial of n
int fact(int n) {
    int res = 1;
    for (int i = 2; i <= n; i++)
        res *= i;
    return res;
}

int nCr(int n, int r) {

    // No valid combinations if r is greater than n
    if (r > n)
        return 0;
    return fact(n) / (fact(r) * fact(n - r));
}

