Output10[Better Approach - 2] Avoiding Factorial Computations - O(n) Time and O(1) SpaceThe formula for nCr is n! / (r!(n-r)!).Instead of computing full factorials, we avoid redundant calculations by recognizing that r! and (n-r)! share common terms that cancel out.To optimize, we compute the product of numbers from r+1 to n and divide it by the product of numbers from 1 to (n-r).Here, r is chosen as the maximum of r and (n-r) to reduce the number of multiplications.This approach avoids large factorial values, reducing computational overhead and preventing integer overflow.Note: This approach may produce incorrect results due to integer overflow when handling large values of n and r.
            C++

    #include <iostream>
using namespace std;

// Calculates the product of natural 
// numbers from start to end
double Multiplier(int start, int end) {
    if (start == end)
        return start;

    double res = 1;
    while (start <= end) {
        res *= start;
        start++;
    }
    return res;
}

int nCr(int n, int r) {
    // No valid combinations if r > n
    if (n < r) 
        return 0;
    // Base cases: nC0 or nCn = 1    
    if (n == r || r == 0) 
        return 1;

    // Use max(r, n-r) to minimize the 
    // number of multiplications
    int max_val = max(r, n - r);
    int min_val = min(r, n - r);

    double nume = Multiplier(max_val + 1, n);
    double deno = Multiplier(1, min_val);

    return int(nume / deno);
}

int main() {
    int n = 5;
    int r = 2;
    cout << nCr(n,min(r,n-r)) << endl; 
    return 0;
}


