Output10[Alternate Approach] Using Logarithmic Formula - O(r) Time and O(1)Logarithmic formula for nCr is an alternative to the factorial formula that avoids computing factorials directly and it's more efficient for large values of n and r. It uses the identity log(n!) = log(1) + log(2) + ... + log(n) to express the numerator and denominator of the nCr in terms of sums of logarithms which allows to calculate the nCr using the Logarithmic operations. This approach is faster and very efficient.The logarithmic formula for nCr is: nCr = exp( log(n!) - log(r!) - log((n-r)!))
            C++

    #include <iostream>
#include <cmath>
using namespace std;

// Calculates the binomial coefficient nCr using logarithmic formula
int nCr(int n, int r) {
    // Invalid case
    if (r > n) return 0;  
    // Base cases
    if (r == 0 || n == r) return 1;    

    double res = 0;
    for (int i = 0; i < r; i++) {
        // log(n!) - log(r!) - log((n-r)!)
        res += log(n - i) - log(i + 1);  
    }

    return (int)round(exp(res));
}

int main() {
    int n = 5;
    int r = 2;
    cout << nCr(n, r) << endl; 
    return 0;
}


